function openingAnnouncement() {
  const upcoming = data.branches.find((item) => item.id === "san-diego");
  if (upcoming?.status === "coming-soon" && upcoming.address && upcoming.mapsUrl?.startsWith("https://www.google.com/maps/")) {
    return `<aside class="opening-announcement opening-announcement--san-diego" aria-labelledby="opening-san-diego">
      <div class="opening-announcement-inner">
        <h2 class="opening-announcement-title" id="opening-san-diego"><span>San Diego</span><span class="opening-announcement-status" data-i18n-es="Próximamente" data-i18n-en="Coming soon">Próximamente</span></h2>
        <div class="opening-announcement-visit"><p class="opening-announcement-address">${escapeHtml(upcoming.address)}</p>
          <a class="opening-announcement-link" href="${escapeHtml(upcoming.mapsUrl)}" target="_blank" rel="noopener noreferrer"><span data-i18n-es="Ver ubicación" data-i18n-en="View location">Ver ubicación</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 10h12m-5-5 5 5-5 5"/></svg></a>
        </div>
      </div>
    </aside>`;
  }
  const branch = data.branches.find((item) => item.id === "el-paso");
  if (!branch || branch.status !== "coming-soon" || branch.openingDate !== "2026-10-09") return "";

  }
}

/* San Diego: the opening state stays visible on the resting card, outside the hover label. */
.opening-announcement--san-diego .opening-announcement-inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(240px, 370px);
  gap: 24px 48px;
  padding-block: 26px;
}
.opening-announcement--san-diego .opening-announcement-title {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px 24px;
  margin: 0;
  font: 400 clamp(44px, 5vw, 64px)/1 "SY Venue Display", Impact, sans-serif;
  letter-spacing: .01em;
}
.opening-announcement--san-diego .opening-announcement-status {
  font: 600 16px/1.4 Inter, sans-serif;
  letter-spacing: 0;
  text-transform: none;
}
.opening-announcement--san-diego .opening-announcement-visit { display: grid; justify-items: start; gap: 8px; }
.opening-announcement--san-diego .opening-announcement-address { margin: 0; max-width: 32ch; font-size: 14px; line-height: 1.55; }
.venue-showcase .venue-coming-soon {
  position: absolute;
  inset: 18px auto auto 18px;
  z-index: 2;
  width: fit-content;
  max-width: calc(100% - 36px);
  padding: 8px 11px;
  border-radius: 4px;
  background: var(--cream);
  color: var(--maroon);
  font: 600 13px/1.3 Inter, sans-serif;
  text-align: center;
  pointer-events: none;
}
.venue-showcase [data-branch-id="san-diego"] .venue-location { top: 62px; }
@media (min-width: 1100px) and (hover: hover) and (pointer: fine) {
  .venue-showcase .venue-gallery:not(.venue-gallery--many) .venue-item:not(.is-open) .venue-coming-soon {
    inset: 18px auto auto 10px;
    width: fit-content;
    max-width: calc(100% - 20px);
    padding: 8px 7px;
    font-size: 12px;
  }
}
@media (max-width: 700px) {
  .opening-announcement--san-diego .opening-announcement-inner { grid-template-columns: minmax(0, 1fr); gap: 14px; padding-block: 24px; }
  .opening-announcement--san-diego .opening-announcement-title { font-size: 48px; gap: 8px 18px; }
}
